const basket = ['apple', 'pear', 'plum', 'apple', 'cherry'];
let count = 0;
for (const fruit of basket) {
  count = count + 1; // one fruit, one more count
}
console.log(count);

const result = [];
let n = 10;
for (let step = 0; step < 6; step = step + 1) {
  result.push(n);
  n = n + 10; // skip up by ten
}
console.log(result.join(' '));
